		params: { parent_node_token: parentNodeToken }
	});
	if (res.code !== 0) throw new Error(res.msg);
	return { nodes: res.data?.items?.map((n) => ({
		node_token: n.node_token,
		obj_token: n.obj_token,
		obj_type: n.obj_type,
		title: n.title,
		has_child: n.has_child
	})) ?? [] };
}
